    return padded;
}

// Example usage of AES-256-GCM for authenticated encryption
std::tuple<std::vector<uint8_t>, std::vector<uint8_t>, std::vector<uint8_t>, std::vector<uint8_t>> 
encrypt_data_secure(const std::vector<uint8_t>& key, const std::vector<uint8_t>& data) {
    // Generate random 128-bit IV and 128-bit authentication tag
    std::vector<uint8_t> iv(AES_BLOCK_SIZE);
    std::vector<uint8_t> tag(AES_BLOCK_SIZE);
    RAND_bytes(iv.data(), iv.size());

    // Use the first 32 bytes of the key for AES-256 encryption
    std::vector<uint8_t> aes_key(key.begin(), key.begin() + 32);

    // Create and initialize the AES cipher context for GCM mode
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, aes_key.data(), iv.data());

    // Pad the data according to PKCS7 standard with block size of 16 bytes (AES block size)
    std::vector<uint8_t> padded_data = pkcs7_pad(data, AES_BLOCK_SIZE);

    // Encrypt the padded data using AES in GCM mode
    std::vector<uint8_t> encrypted(padded_data.size());
    int len;
    EVP_EncryptUpdate(ctx, encrypted.data(), &len, padded_data.data(), padded_data.size());

    // Finalize encryption and get authentication tag
    EVP_EncryptFinal_ex(ctx, encrypted.data() + len, &len);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, AES_BLOCK_SIZE, tag.data());

    EVP_CIPHER_CTX_free(ctx);

    return {encrypted, iv, aes_key, tag};
}

